import {
  DataTable,
  DataTableContent,
  DataTablePagination,
  DataTableToolbar,
  DataTableViewOptions,
  DataTableColumnHeader,
  useDataTable,
  ColumnDef,
} from "@traxion-global/design-system/react";

const tableState = useDataTable();

// Access selected rows for business logic
const selectedIds = Object.keys(tableState.rowSelection);

<DataTable columns={columns} data={data} pageCount={pageCount} enableRowSelection {...tableState}>
  <DataTableToolbar>
    {selectedIds.length > 0 && (
      <Button onClick={() => handleBulkDelete(selectedIds)}>
        Delete ({selectedIds.length})
      </Button>
    )}
  </DataTableToolbar>
  <DataTableContent />
  <DataTablePagination />
</DataTable>

const router = useRouter();
const searchParams = useSearchParams();

const tableState = useDataTable({
  router,
  searchParams,
  namespace: "users",
});

// Simple text column
{ header: "Name", accessorKey: "firstName" }

// Fixed-width column
{ header: "ID", accessorKey: "id", size: 50 }

// Sortable column (use DataTableColumnHeader)
{
  header: ({ column }) => (
    <DataTableColumnHeader column={column} title="Email" />
  ),
  accessorKey: "email",
}

// Custom cell renderer
{
  header: "User",
  accessorKey: "firstName",
  cell: ({ row }) => (
    <div className="flex items-center gap-2">
      <User className="h-4 w-4 text-muted-foreground" />
      <span>{row.original.firstName} {row.original.lastName}</span>
    </div>
  ),
}

// Action buttons column (non-sortable, non-hideable)
{
  id: "actions",
  header: () => <div className="text-right">Actions</div>,
  size: 100,
  enableSorting: false,
  enableHiding: false,
  cell: ({ row }) => (
    <div className="flex gap-2 justify-end">
      <Button size="icon" variant="outline" onClick={() => handleEdit(row.original.id)}>
        <Pencil className="h-4 w-4" />
      </Button>
    </div>
  ),
}

// Row selection checkbox column
{
  id: "select",
  header: ({ table }) => (
    <Checkbox
      checked={
        table.getIsAllPageRowsSelected() ||
        (table.getIsSomePageRowsSelected() && "indeterminate")
      }
      onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
      aria-label="Select all"
    />
  ),
  cell: ({ row }) => (
    <Checkbox
      checked={row.getIsSelected()}
      onCheckedChange={(value) => row.toggleSelected(!!value)}
      aria-label="Select row"
    />
  ),
  enableSorting: false,
  enableHiding: false,
  size: 50,
}

// Column with visibility toggle (set id for display name in menu)
{ id: "Email", header: "Email", accessorKey: "email", enableHiding: true }

// Nested object accessor
{
  id: "Company",
  accessorKey: "company.name",
  header: ({ column }) => (
    <DataTableColumnHeader column={column} title="Company" />
  ),
}

// Multi-line cell for related data
{
  id: "Location",
  accessorKey: "address.city",
  cell: ({ row }) => (
    <div className="flex flex-col">
      <span className="font-medium">{row.original.address.city}</span>
      <span className="text-xs text-muted-foreground">
        {row.original.address.state}, {row.original.address.country}
      </span>
    </div>
  ),
}

import {
  DateRangePicker,
} from "@traxion-global/design-system/react";
import type { DateRange } from "@traxion-global/design-system/react";
import { useState } from "react";

// State inside the component
const [dateRange, setDateRange] = useState<DateRange | undefined>(undefined);

// Inside DataTableToolbar — use DateRangePicker, never <input type="date"> or manual Calendar+Popover
<DateRangePicker
  value={dateRange}
  onChange={(range) => {
    setDateRange(range);
    tableState.setColumnFilters((prev) => {
      const without = prev.filter((f) => f.id !== "myDateColumn");
      return range?.from ? [...without, { id: "myDateColumn", value: range }] : without;
    });
  }}
  numberOfMonths={2}
  localeCode="es"
/>

import { TimePicker, Label } from "@traxion-global/design-system/react";
import { useState } from "react";

const [fromTime, setFromTime] = useState("");

<div className="flex items-center gap-2">
  <Label htmlFor="from-time">Desde</Label>
  <TimePicker
    id="from-time"
    value={fromTime}
    onChange={(e) => {
      setFromTime(e.target.value);
      tableState.setColumnFilters((prev) => {
        const without = prev.filter((f) => f.id !== "time");
        return e.target.value ? [...without, { id: "time", value: e.target.value }] : without;
      });
    }}
    className="w-32"
  />
</div>
